function validate([s, distance]) {
  if (s.length < 2 || s.length > 52) return 's has 2 to 52 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase letters.';
  const count = {};
  for (const ch of s) count[ch] = (count[ch] ?? 0) + 1;
  if (Object.values(count).some(c => c !== 2)) return 'Every letter in s must occur exactly twice.';
  if (distance.length !== 26) return 'distance needs exactly 26 entries.';
  if (distance.some(d => !Number.isInteger(d) || d < 0 || d > 50)) return 'Each distance is between 0 and 50.';
  return null;
}

