function checkDistances(s, distance) {
  const first = new Map();
  for (let i = 0; i < s.length; i++) {
    const letter = s[i];
    if (first.has(letter)) {
      const gap = i - first.get(letter) - 1;
      if (gap !== distance[letter.charCodeAt(0) - 97]) {
        return false;
      }
    } else {
      first.set(letter, i);
    }
  }
  return true;
}

