function checkDistances(s, distance) {
  // Look each letter of the alphabet up directly with indexOf / lastIndexOf.
  for (let c = 0; c < 26; c++) {
    const ch = String.fromCharCode(97 + c);
    const a = s.indexOf(ch);
    if (a === -1) continue;
    const b = s.lastIndexOf(ch);
    if (b - a - 1 !== distance[c]) return false;
  }
  return true;
}

