function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz'.split('');
  for (let i = letters.length - 1; i > 0; i--) { const j = int(0, i); [letters[i], letters[j]] = [letters[j], letters[i]]; }
  const k = size === 'large' ? 26 : int(1, 5);
  const chars = [...letters.slice(0, k), ...letters.slice(0, k)];
  for (let i = chars.length - 1; i > 0; i--) { const j = int(0, i); [chars[i], chars[j]] = [chars[j], chars[i]]; }
  const s = chars.join('');
  // Start from random entries, then write the true gap for every letter present.
  const distance = Array.from({ length: 26 }, () => int(0, 50));
  for (let c = 0; c < 26; c++) {
    const ch = String.fromCharCode(97 + c), a = s.indexOf(ch);
    if (a !== -1) distance[c] = s.lastIndexOf(ch) - a - 1;
  }
  // About half the inputs break one present letter's gap, so both answers occur.
  if (rand() < 0.5) {
    const c = chars[int(0, chars.length - 1)].charCodeAt(0) - 97;
    const wrong = distance[c] === 0 ? 1 : distance[c] === 50 ? 49 : distance[c] + (rand() < 0.5 ? -1 : 1);
    distance[c] = rand() < 0.5 ? wrong : (distance[c] + int(1, 50)) % 51;
  }
  return [s, distance];
}
